  ],
  "paper": {
    "title": "Thoracic outlet syndrome in overhead athletes",
    "authors": "Funakoshi et al.",
    "journal": "JSES International",
    "year": 2024,
    "doi": "10.1016/j.jseint.2023.12.004",
    "url": "https://doi.org/10.1016/j.jseint.2023.12.004",
    "source": "doi",
    "zotero_key": "",
    "full_text": true
  },
  "hook": "A young thrower with a year of shoulder or elbow pain may not have a shoulder or elbow problem.",
  "trust": {
    "level": "Preliminary",
    "design": "Retrospective case series, one hospital",
    "sample": "79 overhead athletes and 102 nonathletes, all had surgery",
    "limitations": [
      "Everyone had surgery after conservative care failed",
      "Only 3 softball athletes, 67 of 79 played baseball",
      "Two thirds of eligible cases were excluded or lost"
    ]
  },
  "did": {
    "question": "How do overhead athletes do after surgery for thoracic outlet syndrome?",
    "facts": [
      {
        "label": "Design",
        "value": "Retrospective, 2 groups"
      },
      {
        "label": "Who",
        "value": "79 athletes, 102 others"
      },
      {
        "label": "Measured",
        "value": "Roos, DASH, ball speed"
      }
    ],
    "bullets": [
      "Reviewed 181 cases that had first rib resection at one hospital between 2015 and 2021.",
      "Split them into 79 overhead athletes and 102 nonathletes, then compared the two groups.",
      "Measured symptoms, grip power, disability scores, return to sport and pitch velocity.",
      "Followed everyone for at least two years, 31 months on average."
    ]
  },
  "results": {
    "stats": [
      {
        "value": "81%",
        "label": "of overhead athletes returned to their previous level",
        "page": 625
      },
      {
        "value": "7.3 mo",
        "label": "average time from surgery back to sport",
        "page": 625
      },
      {
        "value": "p = .88",
        "label": "pitch velocity was unchanged after surgery",
        "page": 625
      }
    ],
    "chart": {
      "title": "Before and after surgery",
      "a_label": "Before",
      "b_label": "After",
      "unit": "",
      "rows": [
        {
          "label": "Disability, athletes",
          "a": [
            37.2,
            22.7
          ],
          "b": [
            7.5,
            11.3
          ]
        },
        {
          "label": "Disability, others",
          "a": [
            43.2,
            18.8
          ],
          "b": [
            25.5,
            22.1
          ]
        },
        {
          "label": "Ball speed kph",
          "a": [
            126.2,
            11.0
          ],
          "b": [
            125.4,
            11.3
          ]
        }
      ],
      "source": "Mean plus or minus SD. Tables III and IV, pp. 624-625."
    },
    "bullets": [
      "Excellent or good results reached 91.1 percent in overhead athletes against 62.8 percent in nonathletes (p. 624).",
      "Ball velocity in 18 pitchers did not change, 126.2 kph before and 125.4 kph after (P = .876, p. 625).",
      "Nothing seen during surgery separated athletes from nonathletes, including scalene muscle size (Table II, p. 623)."
    ]
  },
  "meaning": {
    "summary": "TOS in throwers looks like dominant arm shoulder or elbow pain, and is easy to mistake for a joint injury.",
    "roles": [
      {
        "role": "Athletic Medicine",
        "line": "Consider the neck when throwing arm pain drags on for months."
      },
      {
        "role": "Athletic Performance",
        "line": "Arm pain resisting normal shoulder care may not be a shoulder issue."
      },
      {
        "role": "Sport Coaches",
        "line": "These athletes hurt for a year before surgery. Flag long pain early."
      }
    ]
  },
  "takeaways": {
    "bullets": [
      "Watch for dominant arm pain that lasts beyond a season.",
      "Ask about numbness, coldness and grip strength too.",
      "Plan on months, not weeks, if surgery is needed."
    ],
    "question": "When a thrower's arm pain has run past three months, what is our current path for getting the neck and thoracic outlet looked at?",
    "bottom_line": "Long standing throwing arm pain deserves a neck check."
  }
}

